const results = [];
const now = new Date().toISOString();

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const currentItem = item.json;

  // Intentamos obtener el registro previo de Supabase para este ítem (si existe)
  let existingRecord = null;
  try {
    existingRecord = $('Get a row').all()[i]?.json || null;
  } catch (e) {
    existingRecord = null;
  }

  // Si no existe en la base de datos (es totalmente nuevo)
  if (!existingRecord || !existingRecord.id) {
    results.push({
      json: {
        proceso_id: currentItem.proceso_id || '',
        ente_nombre: currentItem.ente_nombre || '',
        ente_rif: currentItem.ente_rif || '',
        modalidad: currentItem.modalidad || '',
        tipo_objeto: currentItem.tipo_objeto || '',
        descripcion_objeto: currentItem.descripcion_objeto || '',
        sector: currentItem.sector || '',
        estado: currentItem.estado || '', 
        codigo_clasificacion_rnc: currentItem.codigo_clasificacion_rnc || [],
        fecha_limite_retiro: currentItem.fecha_limite_retiro || null,
        fecha_recepcion_ofertas: currentItem.fecha_recepcion_ofertas || null,
        fecha_disponible: currentItem.fecha_disponible || null, // =H Incluimos la fecha para registros nuevos
        url_publica: currentItem.url_publica || '',
        url_pliego: currentItem.url_pliego || '',
        es_modificado: false,
        created_at: now,
        updated_at: now
      }
    });
  } else {
    // Si ya existe, evaluamos si hubo cambios importantes
    const huboCambios = 
      existingRecord.fecha_limite_retiro !== currentItem.fecha_limite_retiro ||
      existingRecord.fecha_recepcion_ofertas !== currentItem.fecha_recepcion_ofertas ||
      existingRecord.descripcion_objeto !== currentItem.descripcion_objeto;

    results.push({
      json: {
        id: existingRecord.id, // Mantenemos el ID original
        proceso_id: currentItem.proceso_id || existingRecord.proceso_id,
        ente_nombre: currentItem.ente_nombre || existingRecord.ente_nombre,
        ente_rif: currentItem.ente_rif || existingRecord.ente_rif,
        modalidad: currentItem.modalidad || existingRecord.modalidad,
        tipo_objeto: currentItem.tipo_objeto || existingRecord.tipo_objeto,
        descripcion_objeto: currentItem.descripcion_objeto || existingRecord.descripcion_objeto,
        sector: currentItem.sector || existingRecord.sector,
        estado: currentItem.estado || existingRecord.estado || '', 
        codigo_clasificacion_rnc: currentItem.codigo_clasificacion_rnc || existingRecord.codigo_clasificacion_rnc,
        fecha_limite_retiro: currentItem.fecha_limite_retiro || existingRecord.fecha_limite_retiro,
        fecha_recepcion_ofertas: currentItem.fecha_recepcion_ofertas || existingRecord.fecha_recepcion_ofertas,
        fecha_disponible: currentItem.fecha_disponible || existingRecord.fecha_disponible || null, // =H Preservamos/actualizamos fecha_disponible
        url_publica: currentItem.url_publica || existingRecord.url_publica,
        url_pliego: currentItem.url_pliego || existingRecord.url_pliego,
        es_modificado: huboCambios ? true : (existingRecord.es_modificado || false),
        created_at: existingRecord.created_at,
        updated_at: huboCambios ? now : (existingRecord.updated_at || now)
      }
    });
  }
}

return results;

const result = [];
for (const item of $input.all()) {
  // Obtenemos los datos originales directamente de la iteración actual del Loop
  const original = $('Loop Over Items').item.json;

  // Limpiar y parsear la respuesta de la IA
  let rawText = item.json.text || item.json.output || "";
  rawText = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

  let sectorElegido = "Servicios Generales y Mantenimiento"; // Fallback por defecto

  try {
    const parsed = JSON.parse(rawText);
    if (parsed.sector) sectorElegido = parsed.sector;
  } catch (e) {
    const match = rawText.match(/"sector"\s*:\s*"([^"]+)"/);
    if (match) sectorElegido = match[1];
  }

  // Construir el objeto único para cada proceso incluyendo fecha_disponible
  result.push({
    json: {
      proceso_id: original.numero_proceso || original.proceso_id,
      ente_nombre: original.organoente || original.ente_nombre,
      ente_rif: original.rif || original.ente_rif,
      modalidad: original.estatus || original.modalidad,
      tipo_objeto: original.objeto_contratacion || original.tipo_objeto,
      descripcion_objeto: original.denominacion_proceso || original.descripcion_objeto,
      sector: sectorElegido,
      estado: original.estado || '', 
      fecha_disponible: original.fecha_disponible || null, 
      url_pliego: original.url_pdf || original.url_publica || ""
    }
  });
}
return result;

// Obtener la fecha local de hoy en formato YYYY-MM-DD
const fechaHoy = new Date().toLocaleDateString('sv-SE');

//const fechaHoy = "2026-10-16";

// Filtrar únicamente los elementos que coincidan con la fecha de hoy
return $input.all().filter(item => {
  return item.json.fecha_disponible === fechaHoy;
});

//return $input.all();

// Tomamos la respuesta de la página 1
const response = $input.first().json;
// Extraemos el total de páginas que reporta la API (ej: 5)
const totalPages = response.data?.pagination?.pages || 1;

const pagesArray = [];
// Generamos un item por cada página que deba consultarse
for (let i = 1; i <= totalPages; i++) {
  pagesArray.push({
    json: {
      pageNumber: i
    }
  });
}

return pagesArray;

