const allItems = [];

// Recorremos todas las respuestas del bucle de páginas
for (const item of $input.all()) {
  const json = item.json;

  // Extraemos la lista de items sin importar la estructura de ScraperAPI
  let itemsList = [];
  if (Array.isArray(json) && json[0]?.data?.items) {
    itemsList = json[0].data.items;
  } else if (json?.data?.items) {
    itemsList = json.data.items;
  } else if (Array.isArray(json?.items)) {
    itemsList = json.items;
  }

  // Agregamos cada licitación de manera plana
  for (const licitacion of itemsList) {
    allItems.push({ json: licitacion });
  }
}

return allItems;

